        AND budget_revenue <= #{param.budgetRevenueMax}


        AND actual_revenue >= #{param.actualRevenueMin}


        AND actual_revenue <= #{param.actualRevenueMax}


        AND budget_cost >= #{param.budgetCostMin}


        AND budget_cost <= #{param.budgetCostMax}


        AND actual_cost >= #{param.actualCostMin}


        AND actual_cost <= #{param.actualCostMax}


