SELECT COUNT(*) as totalOperations, SUM(CASE WHEN management_type = 1 THEN 1 ELSE 0 END) as financeCount, SUM(CASE WHEN management_type = 2 THEN 1 ELSE 0 END) as progressCount, SUM(CASE WHEN management_type = 3 THEN 1 ELSE 0 END) as qualityCount, SUM(CASE WHEN management_type = 4 THEN 1 ELSE 0 END) as safetyCount, SUM(CASE WHEN management_type = 5 THEN 1 ELSE 0 END) as settlementCount, SUM(CASE WHEN management_status = 1 THEN 1 ELSE 0 END) as normalStatus, SUM(CASE WHEN management_status = 2 THEN 1 ELSE 0 END) as warningStatus, SUM(CASE WHEN management_status = 3 THEN 1 ELSE 0 END) as abnormalStatus, SUM(CASE WHEN management_status = 4 THEN 1 ELSE 0 END) as suspendedStatus, AVG(completion_progress) as avgProgress, AVG(quality_score) as avgQualityScore, SUM(planned_amount) as totalPlannedAmount, SUM(actual_amount) as totalActualAmount FROM project_operations
deleted = 0
AND project_id = #{projectId}

SELECT management_type, COUNT(*) as count, AVG(completion_progress) as avgProgress, AVG(quality_score) as avgQualityScore, SUM(planned_amount) as totalPlannedAmount, SUM(actual_amount) as totalActualAmount FROM project_operations
deleted = 0
AND project_id = #{projectId}
AND start_date >= #{startDate}
AND end_date <= #{endDate}
GROUP BY management_type ORDER BY count DESC

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as totalCount, AVG(completion_progress) as avgProgress, AVG(quality_score) as avgQualityScore, SUM(actual_amount) as totalAmount FROM project_operations
deleted = 0
AND project_id = #{projectId}
AND create_time >= #{startDate}
AND create_time <= #{endDate}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC LIMIT 12

SELECT SUM(CASE WHEN management_type = 1 THEN planned_amount ELSE 0 END) as totalBudget, SUM(CASE WHEN management_type = 1 THEN actual_amount ELSE 0 END) as totalExpenditure, SUM(CASE WHEN management_type = 1 AND actual_amount > planned_amount THEN actual_amount - planned_amount ELSE 0 END) as totalOverrun, COUNT(CASE WHEN management_type = 1 AND actual_amount > planned_amount THEN 1 END) as overrunCount, AVG(CASE WHEN management_type = 1 AND planned_amount > 0 THEN (actual_amount / planned_amount) * 100 ELSE 0 END) as avgExecutionRate FROM project_operations
deleted = 0
AND project_id = #{projectId}

