SELECT department, COUNT(*) as totalTasks, AVG(completion_progress) as avgProgress, AVG(quality_score) as avgQualityScore, SUM(CASE WHEN management_status = 1 THEN 1 ELSE 0 END) as normalTasks, SUM(CASE WHEN management_status IN (2, 3) THEN 1 ELSE 0 END) as problemTasks FROM project_operations
deleted = 0 AND department IS NOT NULL
AND project_id = #{projectId}
AND create_time >= #{startDate}
AND create_time <= #{endDate}
GROUP BY department ORDER BY avgProgress DESC, avgQualityScore DESC

SELECT

FROM tbl_project_operations
WHERE del_flag = 0
AND operations_no = #{operationsNo}

    AND id != #{excludeId}

LIMIT 1

SELECT
FROM tbl_project_operations WHERE del_flag = 0 AND ( operations_no LIKE CONCAT('%', #{keyword}, '%') OR project_name LIKE CONCAT('%', #{keyword}, '%') OR manager_name LIKE CONCAT('%', #{keyword}, '%') OR analysis_report LIKE CONCAT('%', #{keyword}, '%') OR remarks LIKE CONCAT('%', #{keyword}, '%') ) ORDER BY create_time DESC
LIMIT #{limit}

SELECT COUNT(*) as totalCount, SUM(CASE WHEN operations_type = 1 THEN 1 ELSE 0 END) as revenueCount, SUM(CASE WHEN operations_type = 2 THEN 1 ELSE 0 END) as costCount, SUM(CASE WHEN operations_type = 3 THEN 1 ELSE 0 END) as profitCount, SUM(CASE WHEN operations_type = 4 THEN 1 ELSE 0 END) as cashFlowCount, SUM(CASE WHEN operations_type = 5 THEN 1 ELSE 0 END) as riskCount, SUM(CASE WHEN operations_type = 6 THEN 1 ELSE 0 END) as performanceCount, SUM(CASE WHEN operations_status = 1 THEN 1 ELSE 0 END) as normalStatus, SUM(CASE WHEN operations_status = 2 THEN 1 ELSE 0 END) as warningStatus, SUM(CASE WHEN operations_status = 3 THEN 1 ELSE 0 END) as abnormalStatus, SUM(CASE WHEN operations_status = 4 THEN 1 ELSE 0 END) as suspendedStatus, SUM(CASE WHEN risk_level = 1 THEN 1 ELSE 0 END) as lowRisk, SUM(CASE WHEN risk_level = 2 THEN 1 ELSE 0 END) as mediumRisk, SUM(CASE WHEN risk_level = 3 THEN 1 ELSE 0 END) as highRisk, SUM(CASE WHEN risk_level >= 4 THEN 1 ELSE 0 END) as veryHighRisk, COALESCE(SUM(contract_amount), 0) as totalContractAmount, COALESCE(SUM(budget_revenue), 0) as totalBudgetRevenue, COALESCE(SUM(actual_revenue), 0) as totalActualRevenue, COALESCE(SUM(budget_cost), 0) as totalBudgetCost, COALESCE(SUM(actual_cost), 0) as totalActualCost, COALESCE(SUM(budget_profit), 0) as totalBudgetProfit, COALESCE(SUM(actual_profit), 0) as totalActualProfit, COALESCE(AVG(profit_rate), 0) as avgProfitRate, COALESCE(AVG(gross_profit_rate), 0) as avgGrossProfitRate, COALESCE(AVG(net_profit_rate), 0) as avgNetProfitRate, COALESCE(AVG(roi), 0) as avgROI, COALESCE(AVG(risk_score), 0) as avgRiskScore, COALESCE(AVG(performance_score), 0) as avgPerformanceScore FROM tbl_project_operations
del_flag = 0
AND project_id = #{param.projectId}
AND operations_type = #{param.operationsType}
AND operations_status = #{param.operationsStatus}
AND risk_level = #{param.riskLevel}
AND manager_id = #{param.managerId}
AND department_id = #{param.departmentId}
AND create_time >= #{param.createTimeStart}
AND create_time <= #{param.createTimeEnd}

SELECT operations_type as type, CASE operations_type WHEN 1 THEN '收入管理' WHEN 2 THEN '成本管理' WHEN 3 THEN '利润分析' WHEN 4 THEN '现金流管理' WHEN 5 THEN '风险控制' WHEN 6 THEN '绩效评估' ELSE '未知' END as typeName, COUNT(*) as count, COALESCE(SUM(contract_amount), 0) as totalAmount, COALESCE(SUM(actual_revenue), 0) as totalRevenue, COALESCE(SUM(actual_cost), 0) as totalCost, COALESCE(SUM(actual_profit), 0) as totalProfit, COALESCE(AVG(profit_rate), 0) as avgProfitRate FROM tbl_project_operations
del_flag = 0
AND project_id = #{param.projectId}
AND create_time >= #{param.createTimeStart}
AND create_time <= #{param.createTimeEnd}
GROUP BY operations_type ORDER BY count DESC

SELECT operations_status as status, CASE operations_status WHEN 1 THEN '正常' WHEN 2 THEN '预警' WHEN 3 THEN '异常' WHEN 4 THEN '停止' ELSE '未知' END as statusName, COUNT(*) as count, COALESCE(SUM(contract_amount), 0) as totalAmount, COALESCE(SUM(actual_revenue), 0) as totalRevenue, COALESCE(SUM(actual_cost), 0) as totalCost, COALESCE(SUM(actual_profit), 0) as totalProfit, COALESCE(AVG(profit_rate), 0) as avgProfitRate FROM tbl_project_operations
del_flag = 0
AND project_id = #{param.projectId}
AND create_time >= #{param.createTimeStart}
AND create_time <= #{param.createTimeEnd}
GROUP BY operations_status ORDER BY count DESC

SELECT risk_level as level, CASE risk_level WHEN 1 THEN '低' WHEN 2 THEN '中' WHEN 3 THEN '高' WHEN 4 THEN '极高' ELSE '未知' END as levelName, COUNT(*) as count, COALESCE(SUM(contract_amount), 0) as totalAmount, COALESCE(SUM(actual_revenue), 0) as totalRevenue, COALESCE(SUM(actual_cost), 0) as totalCost, COALESCE(SUM(actual_profit), 0) as totalProfit, COALESCE(AVG(profit_rate), 0) as avgProfitRate FROM tbl_project_operations
del_flag = 0
AND project_id = #{param.projectId}
AND create_time >= #{param.createTimeStart}
AND create_time <= #{param.createTimeEnd}
GROUP BY risk_level ORDER BY count DESC

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as count, COALESCE(SUM(budget_revenue), 0) as budgetRevenue, COALESCE(SUM(actual_revenue), 0) as actualRevenue, COALESCE(AVG(CASE WHEN budget_revenue > 0 THEN (actual_revenue / budget_revenue) * 100 ELSE 0 END), 0) as completionRate FROM tbl_project_operations
del_flag = 0
AND project_id = #{param.projectId}
AND create_time >= #{param.createTimeStart}
AND create_time <= #{param.createTimeEnd}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC LIMIT 12

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as count, COALESCE(SUM(budget_cost), 0) as budgetCost, COALESCE(SUM(actual_cost), 0) as actualCost, COALESCE(AVG(CASE WHEN budget_cost > 0 THEN (actual_cost / budget_cost) * 100 ELSE 0 END), 0) as controlRate FROM tbl_project_operations
del_flag = 0
AND project_id = #{param.projectId}
AND create_time >= #{param.createTimeStart}
AND create_time <= #{param.createTimeEnd}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC LIMIT 12

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as count, COALESCE(SUM(budget_profit), 0) as budgetProfit, COALESCE(SUM(actual_profit), 0) as actualProfit, COALESCE(AVG(CASE WHEN budget_profit > 0 THEN (actual_profit / budget_profit) * 100 ELSE 0 END), 0) as completionRate, COALESCE(AVG(profit_rate), 0) as avgProfitRate FROM tbl_project_operations
del_flag = 0
AND project_id = #{param.projectId}
AND create_time >= #{param.createTimeStart}
AND create_time <= #{param.createTimeEnd}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC LIMIT 12

